"""Generates scenarios/restart/dormant-*: restart past dormant transactions (fork option
state.dormant-transactions-max). A dormant transaction is open at a checkpoint and has only touched
tables outside OLR's filter; with the option OLR restarts after its begin and recreates it from the
checkpoint. Run: python fixtures/restart-past-dormant/gen.py
"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2] / "scenarios" / "restart"

SETUP = """BEGIN EXECUTE IMMEDIATE 'DROP USER {u} CASCADE';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1918 THEN RAISE; END IF; END;
/
CREATE USER {u} IDENTIFIED BY olrt QUOTA UNLIMITED ON users DEFAULT TABLESPACE users;
CREATE TABLE {u}.t (id NUMBER(10) PRIMARY KEY, v VARCHAR2(40));
ALTER TABLE {u}.t ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
CREATE TABLE {u}.u (id NUMBER(10) PRIMARY KEY, v VARCHAR2(40));
ALTER TABLE {u}.u ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
INSERT INTO {u}.t VALUES (1, 'initial');
INSERT INTO {u}.u SELECT LEVEL, 'initial' FROM dual CONNECT BY LEVEL <= 30;
CREATE TABLE {u}.l (id NUMBER(10) PRIMARY KEY, v VARCHAR2(40));
ALTER TABLE {u}.l ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
COMMIT;
"""

RECREATED = r"recreated [1-9]\d* dormant transaction"
PAST = r"restart past dormant transactions: from seq"


def sql(stmt, session=1):
    s = f'[[step]]\nsql = "{stmt}"\n'
    return s + (f"session = {session}\n" if session != 1 else "")


def commit_and_read(u, row, text, session=1):
    # read idle too: with SHOW_DDL a DDL commit can come first, the offset must be past this commit
    return (sql(f"INSERT INTO {u}.t VALUES ({row}, '{text}')", session) + sql("COMMIT", session)
            + '[[step]]\nread = "commits"\ncount = 1\n[[step]]\nread = "idle"\nidle = 3\n[[step]]\nclient = "commit_offset"\n')


def checkpoint():
    # OLR writes a checkpoint when the sequence changes; two switches put the dormant begin in an older log
    return '[[step]]\nsleep = 3\n[[step]]\nswitch_logfile = true\ncount = 2\n[[step]]\nsleep = 5\n'


def restart(signal="KILL", config=None):
    cfg = f"config = {config}\n" if config else ""
    # as the production init container: the writer checkpoint is deleted, the client's START picks the checkpoint
    return (f'[[step]]\nclient = "disconnect"\n[[step]]\nolr = "stop"\nsignal = "{signal}"\ndelete_writer_checkpoint = true\n'
            f'[[step]]\nolr = "start"\n{cfg}[[step]]\nclient = "connect"\n[[step]]\nread = "idle"\nidle = 8\n')


def head(dormant_max, extra="", equivalence=False):
    eq = ('[equivalence]\n' + ('expect_engaged = false\n' if equivalence == "pinned" else '') + '\n') if equivalence else ""
    return f"[olr]\nqueue_size = 65536\ndormant_max = {dormant_max}\n{extra}\n{eq}" + '[[step]]\nclient = "connect"\n'


def write(name, description, readme, tables, client, expect=(), forbid=(), extra_toml=""):
    # the safety net (60061) must never fire on a correct run
    if not any("60061" in e for e in expect) and "60061" not in forbid:
        forbid = list(forbid) + ["60061"]
    d = ROOT / name
    d.mkdir(parents=True, exist_ok=True)
    u = tables[0].split(".")[0]
    (d / "setup.sql").write_text(SETUP.format(u=u))
    (d / "workload.sql").write_text("-- network mode: the workload is in client.toml\n")
    (d / "client.toml").write_text(client)
    toml = (f'description = "{description}"\n'
            'tags = ["restart", "network", "dormant"]\n'
            f"tables = {list(tables)!r}\n".replace("'", '"')
            + "olr_timeout = 900\n"
            + ('' if "allowed_warnings" in extra_toml else
               # 10061: the client disconnects on purpose. 60010: undo of an unknown (background or other container)
               # transaction after any restart, base behaviour (see the design note)
               'allowed_warnings = ["^10061 network error, errno: 32", "^60010 no match found for transaction rollback"]\n')
            + f"expect_log = {list(expect)!r}\n".replace("'", '"').replace("\\\\", "\\\\")
            + f"forbid_log = {list(forbid)!r}\n".replace("'", '"').replace("\\\\", "\\\\")
            + extra_toml)
    (d / "scenario.toml").write_text(toml)
    (d / "README.md").write_text("Generated by fixtures/restart-past-dormant/gen.py.\n\n" + readme.strip() + "\n")


def basic(name, dormant_max, signal, expect, forbid, readme, n, equivalence=False):
    u = f"OLRT_DRM{n}"
    c = head(dormant_max, equivalence=equivalence)
    c += commit_and_read(u, 2, "before")
    c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
    c += checkpoint()
    c += commit_and_read(u, 3, "after checkpoint")
    c += restart(signal)
    c += sql(f"INSERT INTO {u}.t VALUES (4, 'from the dormant transaction')", 2)
    c += sql("COMMIT", 2)
    c += '[[step]]\nread = "commits"\ncount = 1\n'
    write(name, f"dormant transaction on a table outside the filter open across a {signal} restart, "
          f"dormant-transactions-max {dormant_max}", readme, [f"{u}.T"], c, expect, forbid)


basic("dormant-unfiltered-kill", 1000, "KILL", [PAST, RECREATED], ["60011", "50039"], """
Session 2 updates OLRT_DRM1.U (not in the filter) and stays open over two log switches (checkpoints).
OLR is killed and restarted with `dormant-transactions-max` 1000: it starts at the checkpoint, not at
the begin of the open transaction, and recreates it. The transaction then inserts into T (in the
filter) and commits: the row must arrive with the begin of the transaction (diff, replay).

[equivalence]: the recorded redo is replicated again uninterrupted (A), then restarted from A's newest
checkpoint with dormant-tran with the option (B) and without it (C); B must equal C byte for byte and A
after that SCN apart from the scn field, and B must have used the dormant position.
""", 1, equivalence=True)

basic("dormant-unfiltered-int", 1000, "INT", [PAST, RECREATED], ["60011", "50039"], """
As dormant-unfiltered-kill, with a clean shutdown (SIGINT): the checkpoint written on shutdown carries
the dormant transaction.
""", 2)

basic("dormant-off", 0, "KILL", [], [PAST, "recreated .* dormant", "dormant-tran"], """
Control for dormant-unfiltered-kill with `dormant-transactions-max` 0 (default, feature off): OLR
restarts from min-tran (the begin of the open transaction) and nothing about dormant transactions is
logged or written.
""", 3)

# Dormant at the checkpoint, rows in the filter after it, killed before the commit
u = "OLRT_DRM4"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += checkpoint()
c += sql(f"INSERT INTO {u}.t VALUES (10, 'relevant after the checkpoint')", 2)
c += commit_and_read(u, 3, "after checkpoint")
c += restart("KILL")
# now the dormant transaction holds rows: the next checkpoint must pin it
c += checkpoint()
c += commit_and_read(u, 5, "after the second checkpoint")
c += restart("KILL")
c += sql(f"INSERT INTO {u}.t VALUES (11, 'second row of the dormant transaction')", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-relevant-after-checkpoint", "dormant at a checkpoint, rows in the filter after it, killed twice before the commit",
      """
Session 2 is dormant (only OLRT_DRM4.U) at a checkpoint, then inserts into T without committing.
OLR is killed: the restart starts at that checkpoint, recreates the transaction and reads its insert
again. After the restart a checkpoint is taken while the transaction holds the row, so a second kill
must restart from the begin of the transaction (it now pins min-tran). The commit after the second
restart must deliver both rows.
""", [f"{u}.T"], c, [PAST, RECREATED], ["60011", "50039"])

# Filter change between the checkpoint and the restart
u = "OLRT_DRM5"
c = head(1000, f'filter_tables = ["{u}.T"]')
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += restart("KILL", f'{{ filter_tables = ["{u}.T", "{u}.U"] }}')
c += sql(f"INSERT INTO {u}.u VALUES (100, 'after the restart')", 2)
c += sql(f"INSERT INTO {u}.t VALUES (4, 'after the restart')", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-filter-change", "U added to the filter between the checkpoint and the restart: fall back to min-tran", """
OLR starts with only OLRT_DRM5.T in the filter. Session 2 updates U (not in the filter, so dormant)
and stays open over a checkpoint. OLR is killed and restarted with U added to the filter: the
fingerprint in the checkpoint no longer matches, so OLR must restart from min-tran and read the
update of U again. U changes only in that transaction within the recorded range, so diff and replay
over T and U pass only if the update before the checkpoint arrives.
""", [f"{u}.T", f"{u}.U"], c, ["filter or flags changed since the checkpoint"], ["recreated .* dormant", "60011", "50039"])

# Savepoints and rollbacks
u = "OLRT_DRM6"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += sql("SAVEPOINT a", 2)
c += sql(f"UPDATE {u}.u SET v = 'dormant 2' WHERE id = 2", 2)
c += sql(f"UPDATE {u}.u SET v = 'second dormant' WHERE id = 3", 3)
c += sql(f"UPDATE {u}.u SET v = 'third' WHERE id = 4", 4)
c += sql("SAVEPOINT b", 4)
c += sql(f"INSERT INTO {u}.t VALUES (20, 'rolled back before the checkpoint')", 4)
c += sql("ROLLBACK TO SAVEPOINT b", 4)
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += restart("KILL")
c += sql("ROLLBACK TO SAVEPOINT a", 2)
c += sql(f"INSERT INTO {u}.t VALUES (21, 'after rollback to savepoint a')", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
c += sql(f"INSERT INTO {u}.t VALUES (22, 'rolled back whole')", 3)
c += sql("ROLLBACK", 3)
c += sql(f"INSERT INTO {u}.t VALUES (23, 'after the restart')", 4)
c += sql("COMMIT", 4)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-savepoint-rollback", "rollbacks to savepoints set before the checkpoint, a full rollback and a transaction with rolled-back rows across a restart", """
Session 2 is dormant with a savepoint between two updates of U. Session 3 is dormant. Session 4
inserted into T and rolled that back to a savepoint before the checkpoint: it held rows once, so it
pins the restart position, and sessions 2 and 3 (begun earlier) are recreated. After the kill and
restart session 2 rolls back to its pre-checkpoint savepoint and inserts into T, session 3 inserts and
rolls back completely, session 4 inserts and commits. Expected: rows 21 and 23 only, no rollback
warnings (60010, 70003, 70004).
""", [f"{u}.T"], c, [PAST, RECREATED], ["60011", "50039", "60010", "7000[34]"])

# DDL while a dormant transaction is open
u = "OLRT_DRM7"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += sql(f"ALTER TABLE {u}.t ADD (c VARCHAR2(20))")
c += checkpoint()
c += sql(f"INSERT INTO {u}.t VALUES (3, 'after the DDL', 'c3')") + sql("COMMIT")
c += '[[step]]\nread = "commits"\ncount = 1\n[[step]]\nread = "idle"\nidle = 3\n[[step]]\nclient = "commit_offset"\n'
c += restart("KILL")
c += sql(f"ALTER TABLE {u}.t ADD (d NUMBER)")
c += sql(f"INSERT INTO {u}.t VALUES (4, 'from the dormant transaction', 'c4', 4)", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-ddl", "ALTER TABLE on a filtered table while a dormant transaction is open, before the checkpoint and after the restart", """
Session 2 is dormant (U only). Columns are added to T before the checkpoint and after the restart;
the dormant transaction inserts into T with both new columns after the restart. The DDL transactions
are system transactions (never dormant); the recreated transaction must use the schema current at
its insert.
""", [f"{u}.T"], c, [PAST, RECREATED], ["60011", "50039"], 'logminer_dict = "redo"\n')

# Commit and rollback between the checkpoint and the crash
u = "OLRT_DRM8"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 2", 3)
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += sql(f"INSERT INTO {u}.t VALUES (10, 'committed before the crash')", 2)
c += sql("COMMIT", 2)
c += sql(f"INSERT INTO {u}.t VALUES (11, 'rolled back before the crash')", 3)
c += sql("ROLLBACK", 3)
c += restart("KILL")
c += commit_and_read(u, 12, "after the restart")
write("dormant-commit-before-crash", "dormant transactions commit and roll back between the checkpoint and a kill, before the client read them", """
Sessions 2 and 3 are dormant at the checkpoint. Then session 2 inserts into T and commits, session 3
inserts and rolls back, and OLR is killed before the client read either. The restart from the
checkpoint recreates both, reads their rows again and must deliver row 10 once and never row 11.
""", [f"{u}.T"], c, [PAST, RECREATED], ["60011", "50039"])

# Toggle on -> off -> on
u = "OLRT_DRM9"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += restart("INT", "{ dormant_max = 0 }")
c += commit_and_read(u, 4, "feature off")
c += checkpoint()
c += restart("INT", "{ dormant_max = 1000 }")
c += sql(f"INSERT INTO {u}.t VALUES (5, 'from the dormant transaction')", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-toggle", "option on, restart with it off, restart with it on again, a dormant transaction open throughout", """
The checkpoint written with the option on has dormant-tran; the restart with the option off ignores
it and starts from min-tran. The checkpoints written while off have no dormant-tran, so the restart
with the option on again also starts from min-tran. The dormant transaction's row must arrive.
""", [f"{u}.T"], c, ["restart past them is off, starting from min-tran"], ["recreated .* dormant", "60011", "50039"])

# Many dormant transactions, bounded checkpoint
u = "OLRT_DRM10"
c = head(3)
c += commit_and_read(u, 2, "before")
for s in range(2, 10):
    # LGWR writes an uncommitted change within 3 s: one LWN per begin
    c += sql(f"UPDATE {u}.u SET v = 'dormant {s}' WHERE id = {s}", s) + '[[step]]\nsleep = 4\n'
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += restart("KILL")
for s in range(2, 10):
    c += sql(f"INSERT INTO {u}.t VALUES ({100 + s}, 'session {s}')", s)
    c += sql("COMMIT", s)
c += '[[step]]\nread = "commits"\ncount = 8\ntimeout = 60\n'
write("dormant-many-bounded", "8 dormant transactions with dormant-transactions-max 3", """
Eight sessions are dormant at the checkpoint, the option allows three per checkpoint. The three that
began first are recreated, the others pin the restart position at the begin of the oldest of them.
All eight commit a row after the restart.
""", [f"{u}.T"], c, [PAST, r"recreated [1-3] dormant transaction"], ["60011", "50039"])

# Downgrade to a version without the option
OLD_IMAGE = "old"   # client.toml alias for OLRT_OLD_IMAGE, an OLR without the option
u = "OLRT_DRM11"
c = head(1000)
c += commit_and_read(u, 2, "before")
c += checkpoint()
c += sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
c += checkpoint()
c += commit_and_read(u, 3, "after checkpoint")
c += ('[[step]]\nclient = "disconnect"\n[[step]]\nolr = "stop"\nsignal = "INT"\ndelete_writer_checkpoint = true\n'
      f'[[step]]\nolr = "start"\nimage = "{OLD_IMAGE}"\nconfig = {{ dormant_max = -1 }}\n'
      '[[step]]\nclient = "connect"\n[[step]]\nread = "idle"\nidle = 8\n')
c += sql(f"INSERT INTO {u}.t VALUES (4, 'from the dormant transaction')", 2)
c += sql("COMMIT", 2)
c += '[[step]]\nread = "commits"\ncount = 1\n'
write("dormant-downgrade", "checkpoints written with the option, restart on an older image without it", """
OLR runs with the option, a dormant transaction is open over checkpoints, then OLR is stopped and
started on the older image (OLRT_OLD_IMAGE), which does not know `dormant-tran`. It must reject those checkpoints loudly
(ERROR 20003 "attribute dormant-tran not expected") and use an older one written before the
transaction began (no `dormant-tran`), so the transaction's row still arrives (diff, replay).
""", [f"{u}.T"], c, [r"attribute dormant-tran not expected"], ["60011", "50039"],
      'expect_olr_error = "^20003 .*attribute dormant-tran not expected"\n')


def scenario(name, n, description, readme, body, expect=(), forbid=("60011", "50039"), extra_olr="", extra_toml="", tables=None,
             equivalence=False, dormant_max=1000):
    u = f"OLRT_DRM{n}"
    c = head(dormant_max, extra_olr.format(u=u), equivalence)
    c += commit_and_read(u, 2, "before")
    c += body(u)
    write(name, description, readme, tables or [f"{u}.T"], c, expect, forbid, extra_toml)


def tail_commit(u, session=2, row=4):
    return (sql(f"INSERT INTO {u}.t VALUES ({row}, 'from the dormant transaction')", session) + sql("COMMIT", session)
            + '[[step]]\nread = "commits"\ncount = 1\n')


# Filter reload at runtime, both directions
scenario("dormant-reload-shrink", 12, "filter reloaded from {T, U} to {T} while a dormant transaction updates U, restart with {T, U}", """
OLR starts with T and U in the filter, the filter is reloaded at runtime to T only, then session 2
updates U (dormant under the new filter) over a checkpoint. OLR is killed and restarted with T and U
again. The checkpoint carries the fingerprint of the reloaded filter, so the restart must start from
min-tran and read the update of U again (diff and replay over T and U).
""", lambda u: ('[[step]]\nolr = "reconfigure"\nconfig = { filter_tables = ["' + u + '.T"] }\n'
               + sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint()
               + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL", '{ filter_tables = ["' + u + '.T", "' + u + '.U"] }')
               + sql(f"INSERT INTO {u}.u VALUES (100, 'after the restart')", 2) + tail_commit(u)),
         ["filter or flags changed since the checkpoint|filter changed: transactions open now"], ["recreated .* dormant", "60011", "50039"],
         extra_olr='filter_tables = ["{u}.T", "{u}.U"]', tables=["OLRT_DRM12.T", "OLRT_DRM12.U"])

scenario("dormant-reload-grow", 13, "dormant transaction updates U, filter reloaded from {T} to {T, U}, restart", """
OLR starts with T only. Session 2 updates U (dormant), then the filter is reloaded to T and U while
it is open, a checkpoint follows. Transactions open at a filter change must not be dormant any more:
the kill and restart must read session 2 from its begin, so its update of U before the reload arrives
with the later insert into U (diff and replay over T and U).
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
               + '[[step]]\nsleep = 4\n[[step]]\nolr = "reconfigure"\nconfig = { filter_tables = ["' + u + '.T", "' + u + '.U"] }\n'
               + checkpoint() + commit_and_read(u, 3, "after checkpoint") + restart("KILL")
               + sql(f"INSERT INTO {u}.u VALUES (100, 'after the restart')", 2) + tail_commit(u)),
         ["filter changed: transactions open now"], ["60011", "50039"],
         extra_olr='filter_tables = ["{u}.T"]', tables=["OLRT_DRM13.T", "OLRT_DRM13.U"])

# Schema checkpoint deleted
scenario("dormant-schema-ref-missing", 14, "the checkpoint files other checkpoints take their schema from are deleted before the restart", """
Session 2 is dormant over checkpoints that take their schema from an earlier file (schema-ref-scn).
That file is deleted while OLR is down: the restart cannot load the checkpoint's schema, so it must
not start past the dormant transaction (OLR reads the dictionary again and starts from min-tran).
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL").replace('delete_writer_checkpoint = true\n', 'delete_writer_checkpoint = true\ndelete_schema_ref = true\n')
               + tail_commit(u)),
         [], [PAST, "recreated .* dormant", "60011", "50039"],
         extra_toml='allowed_warnings = ["^10061 network error, errno: 32", "^60010 no match found for transaction rollback", "^10003 file: work/state/FREEPDB1-chkpt-\\\\d+\\\\.json"]\n')

# Deliberately broken seed: the safety net must fire
scenario("dormant-broken-seed", 15, "dormant-tran list emptied while OLR is down: the safety net 60061 must fire", """
As dormant-unfiltered-kill, but the dormant transactions of every checkpoint are moved from list to
pinned before the restart (a deliberately wrong checkpoint: named, but neither recreated nor read from
its begin). OLR starts past the dormant transaction without recreating it, so its commit must raise
WARN 60061. The row is lost by construction: only check run.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL").replace('delete_writer_checkpoint = true\n', 'delete_writer_checkpoint = true\nbreak_dormant_seed = true\n')
               + sql(f"INSERT INTO {u}.t VALUES (4, 'lost')", 2) + sql("COMMIT", 2) + '[[step]]\nread = "idle"\nidle = 5\n'),
         [PAST, r"WARN  60061 commit of transaction"], ["60011", "50039"],
         extra_toml='checks = ["run"]\nexpect_warning = "^60061 "\n')

# Downgrade with no checkpoint without the field, and the rollback with disable-checks 8
def downgrade(u, disable_checks):
    cfg = "{ dormant_max = -1" + (", disable_checks = 8" if disable_checks else "") + " }"
    stop = ('[[step]]\nclient = "disconnect"\n[[step]]\nolr = "stop"\nsignal = "INT"\ndelete_writer_checkpoint = true\n'
            + ('' if disable_checks else 'delete_checkpoints_without = "dormant-tran"\n') +
            f'[[step]]\nolr = "start"\nimage = "{OLD_IMAGE}"\nconfig = {cfg}\n[[step]]\nclient = "connect"\n[[step]]\nread = "idle"\nidle = 8\n')
    return (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
            + checkpoint() + commit_and_read(u, 5, "after checkpoint 2") + stop + tail_commit(u))


scenario("dormant-downgrade-no-plain", 16, "only checkpoints with dormant-tran are kept, restart on an older image", """
Every checkpoint without dormant-tran is deleted before the older image (OLRT_OLD_IMAGE) starts: it rejects all others
(ERROR 20003) and cold-starts. The cold start's low watermark (V$TRANSACTION) covers the open
transaction, so its row still arrives; production without the grant or beyond cold-start-max-age-s
would lose it (see the design note).
""", lambda u: downgrade(u, False), [r"attribute dormant-tran not expected"], ["50039"],
         extra_toml='expect_olr_error = "^20003 .*attribute dormant-tran not expected"\n')

scenario("dormant-downgrade-disable-checks", 17, "downgrade to an older image with reader disable-checks 8 (the rollback procedure)", """
Checkpoints written with the option, then the older image (OLRT_OLD_IMAGE) with reader "disable-checks": 8 (the rollback
procedure): it ignores dormant-tran, reads min-tran of the newest checkpoint and starts from the classic
position. No ERROR 20003, no cold start, the row arrives.
""", lambda u: downgrade(u, True), [], ["20003", "50039", "60011"])


# Flag 1024 (show incomplete transactions) with a dormant transaction open
scenario("dormant-flag-1024", 18, "flags 1024 (show incomplete transactions) with a dormant transaction across a kill", """
With flag 1024 OLR creates transactions whose begin it did not read. A dormant transaction must still
be recreated with its begin (no 60011 for it) and its row arrive.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL") + tail_commit(u)),
         [PAST, RECREATED], ["50039"], extra_toml="olr_flags = 1024\nallowed_warnings = [\"^10061 network error, errno: 32\", \"^60010 no match found for transaction rollback\", \"^60011 \"]\n",
         equivalence=True)

# transaction-max-mb exceeded by a recreated transaction
scenario("dormant-transaction-max", 19, "a recreated transaction exceeds transaction-max-mb after the restart", """
transaction-max-mb is 1. The dormant transaction is recreated and then inserts about 4 MB into T: OLR
drops it as it would without the restart. Only run and the equivalence with a min-tran restart are
checked (the rows are missing by configuration).
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL")
               + sql(f"INSERT INTO {u}.t SELECT 1000 + LEVEL, RPAD('x', 40, 'x') FROM dual CONNECT BY LEVEL <= 40000", 2)
               + sql("COMMIT", 2) + '[[step]]\nread = "idle"\nidle = 5\n' + commit_and_read(u, 6, "after")),
         [PAST, RECREATED], ["60011", "50039"], extra_toml='checks = ["run"]\nolr_source = { "transaction-max-mb" = 1 }\n',
         equivalence=True)

# Dormant begins in the same LWN as the transaction that pins the position
scenario("dormant-same-lwn", 20, "dormant transaction begun in the LWN of the begin of the pinning transaction", """
Sessions 3 (insert into T, pins) and 2 (update of U, dormant) begin right after each other, so both
begins land in the same LWN. The restart starts at that LWN: session 2's begin is read again and it
must not be recreated as well (no 50039). Both then commit.
""", lambda u: (sql(f"INSERT INTO {u}.t VALUES (30, 'pins')", 3) + sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
               + checkpoint() + commit_and_read(u, 3, "after checkpoint") + restart("KILL")
               + sql("COMMIT", 3) + '[[step]]\nread = "commits"\ncount = 1\n' + tail_commit(u)),
         [], ["60011", "50039"])

# Max 1 with the oldest transaction relevant
scenario("dormant-max1-oldest-relevant", 21, "dormant-transactions-max 1, the oldest open transaction holds rows", """
Session 3 inserts into T first (relevant, oldest), sessions 2 and 4 are dormant. With one dormant
transaction allowed, the restart position is never later than min-tran, so no dormant-tran is
written and the restart is the classic one.
""", lambda u: (sql(f"INSERT INTO {u}.t VALUES (30, 'pins')", 3) + '[[step]]\nsleep = 4\n'
               + sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + '[[step]]\nsleep = 4\n'
               + sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 2", 4) + checkpoint()
               + commit_and_read(u, 3, "after checkpoint") + restart("KILL")
               + sql("COMMIT", 3) + '[[step]]\nread = "commits"\ncount = 1\n' + tail_commit(u) + tail_commit(u, 4, 5)),
         [], [PAST, "dormant-tran", "60011", "50039"], dormant_max=1)

# SELECT FOR UPDATE rolled back (undo applied without a buffered row) in a recreated transaction
scenario("dormant-lock-rollback", 22, "recreated transaction locks rows of T and rolls back to a savepoint", """
After the restart the recreated transaction sets a savepoint, locks rows of T (SELECT FOR UPDATE, row
locks are not buffered), rolls back to the savepoint, updates T and rolls back to it again, then
inserts and commits. No 70003/70004 warnings, and the same output as a min-tran restart.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL")
               + sql("SAVEPOINT s", 2)
               + sql(f"BEGIN FOR r IN (SELECT id FROM {u}.t FOR UPDATE) LOOP NULL; END LOOP; END;", 2)
               + sql("ROLLBACK TO SAVEPOINT s", 2) + sql(f"UPDATE {u}.t SET v = 'rolled back' WHERE id = 1", 2)
               + sql("ROLLBACK TO SAVEPOINT s", 2) + tail_commit(u)),
         [PAST, RECREATED], ["60011", "50039", "7000[34]"], equivalence=True)

# Direct-path load into T by a transaction that is dormant at the checkpoint
scenario("dormant-direct-path", 23, "direct-path load into T in a transaction dormant at the checkpoint", """
Session 2 updates U and then loads rows into L (in the filter) with INSERT /*+ APPEND */ (OP 19.1 blocks, not part of
the transaction's rows), stays open over a checkpoint, OLR is killed and restarted. The load is
reported with WARN 60042 before the kill and not again after it (a min-tran restart would report it
again); the rows are missing by OLR's design, so only run and equivalence are checked.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + '[[step]]\nsleep = 4\n'
               + sql(f"INSERT /*+ APPEND */ INTO {u}.l SELECT 1000 + LEVEL, 'load' FROM dual CONNECT BY LEVEL <= 2000", 2)
               + checkpoint() + commit_and_read(u, 3, "after checkpoint") + restart("KILL") + sql("COMMIT", 2)
               + '[[step]]\nread = "idle"\nidle = 5\n' + commit_and_read(u, 6, "after")),
         [PAST], ["60011", "50039"], extra_toml='checks = ["run"]\nallowed_warnings = ["^10061 network error, errno: 32", "^60010 no match found for transaction rollback", "^60042 "]\n',
         equivalence=True, tables=["OLRT_DRM23.T", "OLRT_DRM23.L"])


# Recreated transaction that commits without another change
scenario("dormant-commit-unchanged", 26, "a recreated transaction commits without changing anything after the restart", """
Session 2 is dormant (U only) at the checkpoint, OLR is killed and restarted past it, then session 2
commits without another change: nothing is sent for it, the same as without the restart (equivalence).
Its commit still takes a stream position, as the session records it buffered before the restart
position make it do in a run that reads its begin: the transaction session 1 commits right after it
must get the same position (c_scn, c_idx) and the checkpoints the same position SCN with the option on
and off (equivalence B and C), and no commit below the position (60048) may appear in one run only.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL") + sql("COMMIT", 2) + commit_and_read(u, 4, "right after the dormant commit")
               + '[[step]]\nread = "idle"\nidle = 5\n' + commit_and_read(u, 5, "after")),
         [PAST, RECREATED], ["60011", "50039"], equivalence=True)

scenario("dormant-commit-then-confirm-mid-txn", 31, "a recreated transaction commits unchanged, the client confirms in the middle of the next one, OLR restarts", """
Session 2 is dormant (U only) at the checkpoint; OLR is killed and restarted past it and recreates it.
Session 2 then commits without another change, and session 1 commits 3000 rows into T. The client
reads part of them, keeps the offset (c_scn, c_idx) in the middle of that transaction, and OLR is
killed with the writer checkpoint deleted, so the restart picks a schema checkpoint by its position
file. The rest of the 3000 rows must arrive (diff, replay) at the positions a run without the option
gives them (equivalence B and C: messages, checkpoint position SCNs and 60048 identical).

With commit SCNs in redo order (one instance) the dormant commit cannot be above the next commit,
so this does not reproduce the commit below the position (a later commit record with a lower SCN,
60048) that the unit test DormantPositionTest covers; it covers the restart flow around it.
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + restart("KILL") + sql("COMMIT", 2)
               + sql(f"INSERT INTO {u}.t SELECT 1000 + LEVEL, 'big-' || LEVEL FROM dual CONNECT BY LEVEL <= 3000") + sql("COMMIT")
               + '[[step]]\nread = "messages"\ncount = 1200\ntimeout = 60\n[[step]]\nclient = "commit_offset"\n'
               + '[[step]]\nclient = "disconnect"\n[[step]]\nolr = "restart"\nsignal = "KILL"\ndelete_writer_checkpoint = true\n'
               + '[[step]]\nclient = "connect"\n[[step]]\nread = "idle"\nidle = 10\n[[step]]\nclient = "commit_offset"\n'
               + commit_and_read(u, 5000, "after")),
         [PAST, RECREATED], ["60011", "50039"], equivalence=True)

scenario("dormant-buffered-commit-below-position", 32, "a recreated transaction with session records commits, the next commit lies below it (test build), the client confirms in the middle of it", """
Needs an image built with -DOLR_TEST_HOOKS (make image-test-hooks); other images skip it.

Session 2 sets its client info and starts a transaction with DBMS_TRANSACTION.LOCAL_TRANSACTION_ID(TRUE): Oracle
writes the begin as 5.2 5.1 5.19, and OLR buffers the 5.1 + 5.19 pair as a session chunk, so the
transaction is dormant with "buffered": 1 (a DML statement first writes 5.2 5.1 11.x 5.19 and nothing is
buffered). It updates U (outside the filter) and stays open over checkpoints. Session 1 inserts 3000
rows into L, session 2 commits (COMMIT WRITE BATCH NOWAIT), session 1 commits right after it.

A single-instance Oracle Free writes commit records in SCN order (no inversion in about 100 000
concurrent commits, also with COMMIT WRITE NOWAIT/BATCH), so the test build places the commit of L 1
below the commit of session 2's transaction (OLR_TEST_COMMIT_BELOW_TABLE/CLIENT_INFO), as redo of several
strands or threads can: 60048, and the rows of L are sent at session 2's commit SCN.

The client keeps an offset in the middle of those rows and OLR is killed with the writer checkpoint
deleted. The restart picks a checkpoint from before session 2's commit (its position is below the start
SCN), starts past session 2 and recreates it. Its commit has to move the stream position like the
commit read from its begin, or the rest of L, committed below the start SCN, is never sent (diff,
replay; equivalence B against C: messages, positions and 60048 identical).
""", lambda u: (sql("BEGIN DBMS_APPLICATION_INFO.SET_CLIENT_INFO('olrt_dormant'); END;", 2) + sql("SELECT DBMS_TRANSACTION.LOCAL_TRANSACTION_ID(TRUE) FROM dual", 2)
               + sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2)
               + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + sql(f"INSERT INTO {u}.l SELECT LEVEL, 'below-' || LEVEL FROM dual CONNECT BY LEVEL <= 3000")
               + sql("COMMIT WRITE BATCH NOWAIT", 2) + sql("COMMIT")
               + '[[step]]\nread = "messages"\ncount = 1200\ntimeout = 60\n[[step]]\nclient = "commit_offset"\n'
               + '[[step]]\nclient = "disconnect"\n[[step]]\nolr = "restart"\nsignal = "KILL"\ndelete_writer_checkpoint = true\n'
               + '[[step]]\nclient = "connect"\n[[step]]\nread = "idle"\nidle = 10\n[[step]]\nclient = "commit_offset"\n'
               + commit_and_read(u, 5, "after")),
         [PAST, RECREATED, r"60048 transaction committed below the stream position"], ["60011", "50039"],
         extra_olr='requires_module = "test-hooks"\nenv = {{ OLR_TEST_COMMIT_BELOW_TABLE = "{u}.L", OLR_TEST_COMMIT_BELOW_CLIENT_INFO = "olrt_dormant" }}',
         extra_toml='allowed_warnings = ["^10061 network error, errno: 32", "^60010 no match found for transaction rollback", '
                    '"^60048 transaction committed below the stream position"]\n',
         tables=["OLRT_DRM32.T", "OLRT_DRM32.L"], equivalence=True)

# Filter reload after the state was computed, kill before the next checkpoint
scenario("dormant-reload-before-kill", 27, "filter reloaded to add U after a checkpoint with dormant-tran, killed before the next checkpoint", """
OLR runs with T only. Session 2 updates U (dormant) over a checkpoint, then the filter is reloaded
with U added and OLR is killed before it writes another checkpoint. The restart reads that checkpoint
with the new configuration: the fingerprint differs, so it must start from min-tran and read the
update of U again (diff and replay over T and U).
""", lambda u: (sql(f"UPDATE {u}.u SET v = 'dormant' WHERE id = 1", 2) + checkpoint() + commit_and_read(u, 3, "after checkpoint")
               + '[[step]]\nolr = "reconfigure"\nconfig = { filter_tables = ["' + u + '.T", "' + u + '.U"] }\n'
               + restart("KILL") + sql(f"INSERT INTO {u}.u VALUES (100, 'after the restart')", 2) + tail_commit(u)),
         ["filter or flags changed since the checkpoint"], ["recreated .* dormant", "60011", "50039"],
         extra_olr='filter_tables = ["{u}.T"]', tables=["OLRT_DRM27.T", "OLRT_DRM27.U"])
